<?php

declare(strict_types=1);
require __DIR__ . DIRECTORY_SEPARATOR . 'config.php';
require_admin();
$notice = (string) ($_GET['notice'] ?? '');
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = (string) ($_POST['action'] ?? '');
    $all = coupons();
    if ($action === 'create') {
        $code = strtoupper(trim((string) $_POST['code']));
        $emails = array_values(array_filter(array_map('trim', preg_split('/[,\s]+/', (string) $_POST['emails']))));
        $all[] = ['code'=>$code,'type'=>$_POST['type']==='fixed'?'fixed':'percent','value'=>max(1,(int) $_POST['value']),'product'=>trim((string) $_POST['product']) ?: 'all','emails'=>$emails,'expires_at'=>trim((string) $_POST['expires_at']),'max_uses'=>max(0,(int) $_POST['max_uses']),'used'=>0,'active'=>true];
        save_coupons($all); header('Location: admin-coupons.php?notice=Coupon+created'); exit;
    }
    if ($action === 'toggle') { foreach ($all as &$coupon) if ($coupon['code'] === $_POST['code']) $coupon['active'] = empty($coupon['active']); save_coupons($all); header('Location: admin-coupons.php?notice=Coupon+updated'); exit; }
    if ($action === 'delete') { $all = array_values(array_filter($all, fn(array $coupon): bool => $coupon['code'] !== $_POST['code'])); save_coupons($all); header('Location: admin-coupons.php?notice=Coupon+deleted'); exit; }
}
$all = coupons();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coupons | RankSetu Admin</title><style>body{margin:0;background:#efece2;font:16px Arial;color:#1c1a15}.wrap{width:min(1000px,calc(100% - 40px));margin:auto;padding:40px 0}h1,h2{font-family:Georgia;color:#16233f}.panel{background:#f8f6ee;border:1px solid #cfc7ac;padding:24px;margin:18px 0}label{display:block;font-size:.8rem;font-weight:bold;margin:12px 0 5px}input,select{width:100%;padding:10px;box-sizing:border-box;border:1px solid #cfc7ac;background:#fffdf7}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.btn{background:#9c3b2e;color:#fff;border:0;padding:10px 14px;font-weight:bold;cursor:pointer}.link{color:#9c3b2e;text-decoration:none;margin-left:15px}.notice{padding:12px;background:#e0f0e6;color:#174b32}@media(max-width:650px){.grid{grid-template-columns:1fr}}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px 6px;border-bottom:1px solid #cfc7ac;font-size:.85rem}</style></head><body><main class="wrap"><h1>Coupon manager</h1><p>Create coupons for everyone or restrict them to selected email addresses.</p><a class="link" href="admin.php">Back to admin</a><?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><section class="panel"><h2>Create coupon</h2><form method="post"><input type="hidden" name="action" value="create"><div class="grid"><div><label>Code</label><input name="code" required placeholder="UPSC20"></div><div><label>Discount type</label><select name="type"><option value="percent">Percentage</option><option value="fixed">Fixed INR</option></select></div><div><label>Value</label><input type="number" name="value" min="1" required placeholder="20"></div><div><label>Product slug or all</label><input name="product" value="all" placeholder="all or upsc-full-length"></div><div><label>Allowed emails</label><input name="emails" placeholder="blank = everyone; comma separated emails"></div><div><label>Expiry date</label><input type="date" name="expires_at"></div><div><label>Maximum uses, 0 = unlimited</label><input type="number" name="max_uses" min="0" value="0"></div></div><button class="btn" type="submit">Create coupon</button></form></section><section class="panel"><h2>Existing coupons</h2><table><tr><th>Code</th><th>Discount</th><th>Audience</th><th>Status</th><th></th></tr><?php foreach($all as $coupon):?><tr><td><?=e($coupon['code'])?></td><td><?=e((string)$coupon['value']).($coupon['type']==='percent'?'%':' INR')?></td><td><?=empty($coupon['emails'])?'Everyone':e(implode(', ',$coupon['emails']))?></td><td><?=!empty($coupon['active'])?'Active':'Inactive'?></td><td><form method="post" style="display:inline"><input type="hidden" name="action" value="toggle"><input type="hidden" name="code" value="<?=e($coupon['code'])?>"><button class="btn" type="submit">Toggle</button></form> <form method="post" style="display:inline"><input type="hidden" name="action" value="delete"><input type="hidden" name="code" value="<?=e($coupon['code'])?>"><button class="btn" type="submit">Delete</button></form></td></tr><?php endforeach;?></table></section></main></body></html>
